<template><section><el-form inline size="small" @submit.native.prevent="search"><el-form-item label="业务类型"><el-select v-model="query.kind" clearable><el-option v-for="t in types" :key="t" :value="t" :label="names[t]" /></el-select></el-form-item><el-form-item label="店铺"><el-select v-model="query.channelId" clearable filterable><el-option v-for="c in channels" :key="c.channel_id" :value="c.channel_id" :label="c.channel_name" /></el-select></el-form-item><el-form-item label="状态"><el-select v-model="query.state" clearable><el-option v-for="(v,k) in states" :key="k" :value="k" :label="v" /></el-select></el-form-item><el-form-item label="任务编号"><el-input v-model.trim="query.taskId" clearable placeholder="配合业务类型精确查询" /></el-form-item><el-form-item><el-button type="primary" @click="search">查询</el-button><el-button @click="reset">重置</el-button></el-form-item></el-form><div class="toolbar"><p class="hint">任务由业务类型和编号共同区分；补拉不改变自动游标。统计尚未采集时显示“—”。</p><el-button size="small" @click="load">刷新任务</el-button></div><el-table v-loading="loading" :data="rows" row-key="task_key"><el-table-column label="类型 / 编号" min-width="120"><template slot-scope="s"><el-tag size="small">{{ names[s.row.kind] }}</el-tag><div class="hint">#{{ s.row.id }}</div></template></el-table-column><el-table-column label="店铺 / 发起时间" min-width="210"><template slot-scope="s">{{ shop(s.row.channel_id) }}<div class="hint">{{ s.row.create_time }} · {{ s.row.actor }}</div></template></el-table-column><el-table-column label="方式 / 范围" min-width="200"><template slot-scope="s">{{ modes[s.row.mode] }}<div v-if="s.row.mode!=='IDS'" class="hint">{{ s.row.start_time }}<br>{{ s.row.end_time }}</div></template></el-table-column><el-table-column label="处理结果" min-width="240"><template slot-scope="s"><div>已读取 {{ s.row.read_count }} 条</div><div class="hint">新增 {{ stat(s.row.new_count) }} · 更新 {{ stat(s.row.updated_count) }} · 未变 {{ stat(s.row.unchanged_count) }} · 异常 {{ stat(s.row.failed_count) }}</div></template></el-table-column><el-table-column label="状态 / 异常" min-width="230"><template slot-scope="s"><el-tag size="small" :type="['FAILED','RETRY','PARTIAL'].includes(s.row.state)?'warning':s.row.state==='COMPLETED'?'success':'info'">{{ states[s.row.state] || s.row.state }}</el-tag><div class="warning">{{ s.row.last_error }}</div><message-progress v-if="s.row.message" :message="s.row.message" :type="s.row.kind==='REFUND'?'REFUND_PULL':s.row.kind==='EXCHANGE'?'EXCHANGE_PULL':'ORDER_PULL'"/></template></el-table-column><el-table-column label="操作" width="150" fixed="right"><template slot-scope="s"><el-button type="text" @click="detail(s.row)">结果</el-button><el-button v-if="syncTypes.includes(s.row.kind) && retryAction(s.row)" type="text" :loading="retrying===s.row.task_key" @click="retry(s.row)">{{ retryAction(s.row)==='items'?'重试失败项':'重试' }}</el-button></template></el-table-column></el-table><pagination v-show="total>0" :total="total" :page.sync="query.pageNum" :limit.sync="query.pageSize" @pagination="load" /><order-backfill-task ref="orderTask" @changed="load" /><el-dialog :title="detailTitle" :visible.sync="visible" width="90%" append-to-body><div v-if="record"><el-alert v-if="record.last_error" :title="record.last_error" type="warning" :closable="false" /><message-progress v-if="record.message" :message="record.message" :type="detailKind==='EXCHANGE'?'EXCHANGE_PULL':'REFUND_PULL'"/><p v-if="detailKind==='EXCHANGE'" class="hint">当前阶段：第 {{ record.page_no }} 页 · {{ record.phase==='LIST'?'拉取申请列表':'逐单保存详情' }}；成功项保留，失败项可单独续跑。</p><p>任务状态：{{ states[record.state] || record.state }} · 已读取 {{ record.synced_count }} 条</p><p class="hint">{{ detailKind==='EXCHANGE' ? '同步平台申请不代表已同意换货或执行库存操作。' : '这里只展示来源保存结果，转单及业务处理需进入平台退款或业务退款核对。' }}</p><el-table :data="record.items"><el-table-column :label="detailKind==='EXCHANGE'?'平台换货单号':'平台退款单号'" min-width="210"><template slot-scope="s"><router-link v-if="s.row.platform_exchange_id" :to="{path:'/oms-order/platformExchanges',query:{id:s.row.platform_exchange_id}}">{{ s.row.dispute_id }}</router-link><span v-else>{{ s.row.dispute_id || s.row.refund_id }}</span></template></el-table-column><el-table-column label="结果" width="150"><template slot-scope="s">{{ itemStates[s.row.result] || s.row.result }}</template></el-table-column><el-table-column prop="message" label="说明" min-width="280" /><el-table-column label="单据" min-width="240"><template slot-scope="s"><router-link v-if="s.row.exchange_id" :to="{path:'/oms-order/exchanges',query:{exchangeId:s.row.exchange_id}}">{{ s.row.exchange_sn }}</router-link><router-link v-else-if="s.row.platform_refund_id" :to="{path:'/oms-order/platformRefunds',query:{id:s.row.platform_refund_id}}">查看平台退款</router-link></template></el-table-column><el-table-column v-if="detailKind==='EXCHANGE'" label="日志" width="140"><template slot-scope="s"><platform-log-link :number="s.row.dispute_id" number-type="PLATFORM_EXCHANGE" /></template></el-table-column></el-table><p v-if="record.item_count>100" class="hint">当前展示最近100条，共 {{ record.item_count }} 条；完整业务记录可在换货列表查询。</p></div><span slot="footer"><platform-log-link v-if="detailKind==='REFUND'" :number="'REFSYNC'+detailId" number-type="TASK" /><el-button @click="reloadDetail">刷新结果</el-button><el-button @click="visible=false">关闭</el-button></span></el-dialog></section></template>
<script>
import { intakeTasks, exchangeSyncTask, retryExchangeSync } from '@/api/order/intake'
import { refundTask, retryRefundTask } from '@/api/order/refund'
import { retryPullTask, retryPullItems } from '@/api/order'
import OrderBackfillTask from './OrderBackfillTask'
import MessageProgress from '@/views/oms/messaging/MessageProgress'
import PlatformLogLink from '@/views/oms/channel/PlatformLogLink'
import { intakeKinds, taskStates, itemStates, retryAction } from './intakePresentation'
const defaults=()=>({kind:'',channelId:'',state:'',taskId:'',pageNum:1,pageSize:20})
export default { name:'IntakeTasks', components:{OrderBackfillTask,PlatformLogLink,MessageProgress}, props:{channels:Array,types:Array,syncTypes:Array},data:()=>({query:defaults(),rows:[],total:0,loading:false,loadSequence:0,retrying:'',visible:false,record:null,detailKind:'',detailId:0,names:intakeKinds,states:taskStates,itemStates,modes:{AUTO:'自动同步',MANUAL:'时间补拉',IDS:'指定单号'}}),computed:{detailTitle(){return `${this.names[this.detailKind] || ''}同步任务 #${this.detailId}`}},created(){this.load()},methods:{
 retryAction,stat(n){return n==null?'—':n},shop(id){const c=this.channels.find(c=>Number(c.channel_id)===Number(id));return c?c.channel_name:`渠道 ${id}`},async load(){const seq=++this.loadSequence;this.loading=true;try{const r=(await intakeTasks(this.query)).data;if(seq!==this.loadSequence)return;this.rows=r.rows;this.total=Number(r.total)}finally{if(seq===this.loadSequence)this.loading=false}},search(){this.query.pageNum=1;this.load()},reset(){this.query=defaults();this.load()},filter(kind,taskId=''){this.query.kind=kind;this.query.taskId=String(taskId);this.search()},
 async detail(t){if(t.kind==='ORDER')return this.$refs.orderTask.open([t.id]);this.detailKind=t.kind;this.detailId=t.id;this.record=null;this.visible=true;await this.reloadDetail()},async reloadDetail(){this.record=(await(this.detailKind==='REFUND'?refundTask(this.detailId):exchangeSyncTask(this.detailId))).data},
 async retry(t){this.retrying=t.task_key;try{if(t.kind==='ORDER'){if(retryAction(t)==='items')await retryPullItems(t.id);else await retryPullTask(t.id)}else if(t.kind==='REFUND')await retryRefundTask(t.id);else await retryExchangeSync(t.id);this.$message.success('已提交重试，成功项保持原处理结果');await this.load()}finally{this.retrying=''}}
} }
</script>
<style scoped>.toolbar{display:flex;justify-content:space-between;align-items:center;margin-bottom:16px}.hint{color:#8492a6;font-size:12px;line-height:1.8}.warning{color:#b77515;line-height:1.8}</style>
